package com.fintrack.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService { private final SecretKey key; private final long expiration; public JwtService(@Value("${fintrack.jwt.secret}")String secret,@Value("${fintrack.jwt.expiration}")long expiration){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;} public String generate(String email,Long id){Date n=new Date();return Jwts.builder().subject(email).claim("userId",id).issuedAt(n).expiration(new Date(n.getTime()+expiration)).signWith(key).compact();} public String email(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token){try{email(token);return true;}catch(Exception e){return false;}} }
